def typed_dict_from_dict(d: TypeDict) ->type:
    module = d["module"]
    qualname = d["qualname"]
    elem_types = d["elem_types"]

    # Create the TypedDict class dynamically
    annotations = {}
    for k, v in elem_types.items():
        annotations[k] = type_from_dict(v)

    # Use the proper TypedDict constructor
    return TypedDict(qualname, annotations, module=module)
